func TestG14_ThresholdScopeAndNoRules(t *testing.T) {
	handler := `package transport
import (
	"example.com/test/gen/api"
	"example.com/test/service/billing"
	"example.com/test/service/users"
)
type Handler struct { Users *users.Store; Billing *billing.Store }
func (h *Handler) Handle() *api.Response {
	return &api.Response{Value: h.Users.Load() + h.Billing.Load()}
}
`
	packages := fakeModule(t, layerPolicyFixture(handler))
	if findings := ScanLayerPolicy(packages, nil); len(findings) != 0 {
		t.Fatalf("G14 must be opt-in, got %+v", findings)
	}
	rule := testLayerPolicyRule()
	rule.MaxCoordinatedDependencies = 2
	if findings := ScanLayerPolicy(packages, []LayerPolicyRule{rule}); containsID(findings, "G14") {
		t.Fatalf("configured threshold should allow two dependencies, got %+v", findings)
	}
	rule = testLayerPolicyRule()
	rule.Paths = []string{"delivery/**"}
	if findings := ScanLayerPolicy(packages, []LayerPolicyRule{rule}); containsID(findings, "G14") {
		t.Fatalf("out-of-scope package should not fire, got %+v", findings)
	}
}

func TestValidateLayerPolicyRules(t *testing.T) {
	valid := testLayerPolicyRule()
	if err := ValidateLayerPolicyRules([]LayerPolicyRule{valid}); err != nil {
		t.Fatal(err)
	}
	for name, mutate := range map[string]func(*LayerPolicyRule){
		"name":         func(rule *LayerPolicyRule) { rule.Name = "" },
		"paths":        func(rule *LayerPolicyRule) { rule.Paths = nil },
		"dependencies": func(rule *LayerPolicyRule) { rule.Dependencies = nil },
		"generated":    func(rule *LayerPolicyRule) { rule.GeneratedTypes = nil },
		"threshold":    func(rule *LayerPolicyRule) { rule.MaxCoordinatedDependencies = -1 },
		"severity":     func(rule *LayerPolicyRule) { rule.Severity = "UNKNOWN" },
	} {
		t.Run(name, func(t *testing.T) {
			rule := valid
			mutate(&rule)
			if err := ValidateLayerPolicyRules([]LayerPolicyRule{rule}); err == nil {
				t.Fatal("expected validation error")
			}
		})
	}
	if err := ValidateLayerPolicyRules([]LayerPolicyRule{valid, valid}); err == nil {
		t.Fatal("expected duplicate rule validation error")
	}
}

func TestPolicyPatternMatching(t *testing.T) {
	for _, test := range []struct {
		pattern, value, module string
	}{
		{"internal/transport/**", "github.com/acme/app/internal/transport", "github.com/acme/app"},
		{"internal/transport/**", "github.com/acme/app/internal/transport/http/handler.go", "github.com/acme/app"},
		{"github.com/acme/shared/*", "github.com/acme/shared/store", "github.com/acme/app"},
	} {
		if !matchesPolicyPatterns([]string{test.pattern}, test.value, test.module) {
			t.Fatalf("pattern %q should match %q", test.pattern, test.value)
		}
	}
	if matchesPolicyPatterns([]string{"internal/transport/**"}, "github.com/acme/app/internal/service", "github.com/acme/app") {
		t.Fatal("transport pattern should not match service package")
	}
}
